import{_ as a,o as l,c as e,a2 as i}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"理论/计算机网络/HTTP.md","filePath":"理论/计算机网络/HTTP.md","lastUpdated":1767873102000}'),r={name:"理论/计算机网络/HTTP.md"};function h(o,t,p,s,n,d){return l(),e("div",null,[...t[0]||(t[0]=[i('<h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><h3 id="get" tabindex="-1">Get <a class="header-anchor" href="#get" aria-label="Permalink to &quot;Get&quot;">​</a></h3><ul><li>用于信息获取，应该是安全的和幂等的</li><li>Get 请求的数据会附在 URL 之后</li><li>安全性较低</li><li>传输的数据量较小（2083 个字符）</li></ul><h3 id="post" tabindex="-1">Post <a class="header-anchor" href="#post" aria-label="Permalink to &quot;Post&quot;">​</a></h3><ul><li>可能修改变服务器上的资源的请求</li><li>Post 提交的数据放在 http 请求体中</li><li>安全性较高</li><li>可以传输的数据量比较大</li></ul><h3 id="常见错误码" tabindex="-1">常见错误码 <a class="header-anchor" href="#常见错误码" aria-label="Permalink to &quot;常见错误码&quot;">​</a></h3><p>x</p><h3 id="http1-1-和-http-1-0-的区别" tabindex="-1">Http1.1 和 Http 1.0 的区别 <a class="header-anchor" href="#http1-1-和-http-1-0-的区别" aria-label="Permalink to &quot;Http1.1 和 Http 1.0 的区别&quot;">​</a></h3><ul><li>Http1.0 短连接：每次请求都需要建立一次 TCP 连接，如果网页需要多个图片则需要建立多次 Http 连接</li><li>Http1.1 长连接：支持一个TCP连接上可以传送多个HTTP请求和响应，减少了建立和关闭连接的消耗和延迟。采用流水线的持久连接，不需要等待请求返回就可以发送下一次请求。但是服务端需要按序返回。</li><li>Http1.0 不支持Host请求头字段，无法支持一个主机上的多个虚拟 web 站点</li><li>Http1.1 新增 Host 请求字段，支持一个主机上的多个虚拟 web 站点</li><li>Http1.1 还提供了与身份认证、状态管理和Cache缓存等机制相关的请求头和响应头</li><li>Http1.1 增加了OPTIONS方法，它允许客户端获取一个服务器支持的方法列表</li></ul><h3 id="http1-1-长连接" tabindex="-1">Http1.1 长连接 <a class="header-anchor" href="#http1-1-长连接" aria-label="Permalink to &quot;Http1.1 长连接&quot;">​</a></h3><ul><li>服务端在响应头中加入 Connection:keep-alive</li><li>当一个网页打开完成后，客户端和服务器之间用于传输HTTP数据的 TCP连接不会关闭，如果客户端再次访问这个服务器上的网页，会继续使用这一条已经建立的连接。</li><li>实现长连接要客户端和服务端都支持长连接。</li></ul><h3 id="https-如何进行加密" tabindex="-1">Https 如何进行加密 <a class="header-anchor" href="#https-如何进行加密" aria-label="Permalink to &quot;Https 如何进行加密&quot;">​</a></h3><ul><li>HTTPS(Secure Hypertext Transfer Protocol)安全超文本传输协议</li><li>使用 SSL 在发送方把原始数据进行加密，然后在接受方进行解密保证数据的安全性</li><li>默认端口 443</li></ul><h3 id="http-与-https-的区别" tabindex="-1">Http 与 Https 的区别 <a class="header-anchor" href="#http-与-https-的区别" aria-label="Permalink to &quot;Http 与 Https 的区别&quot;">​</a></h3><ul><li>http是HTTP协议运行在TCP之上。</li><li>https是HTTP运行在SSL/TLS之上，SSL/TLS运行在TCP之上。</li><li>http是超文本传输协议，信息是明文传输</li><li>https 则是具有安全性的ssl加密传输协议</li></ul>',15)])])}const c=a(r,[["render",h]]);export{u as __pageData,c as default};
